nClPeptide<-248


Norm<-function(F,N)

{
No<-matrix(0,20,8)
  colnames(No)<-c("N4","N3","N2","N1","C1","C2","C3","C4")
	for (j in 1:8){
		for (k in 1:20){
			No[k,j]=(F[k,j]/N)*100
		}
	}
	return(No)
}
