CumulativeY<-function(k,b,F)
{
  if( b<=0)
    {
	    cum=0
	}
  else
    {
	    cum=0
	    for(d in 1:b)
    {
        cum=cum + (round(F[d,k]))

        }
     }
return(cum)
}
